            <div v-else class="legal-delete-list"><a-empty v-if="!groupForm.legalFiles.length" description="暂无可删除的法人章"/><div v-else class="legal-file-list"><div v-for="file in groupForm.legalFiles" :key="file.uid" class="legal-file-item"><a-image :width="48" :height="48" :src="sealImageUrl" :preview="{src:sealImageUrl}"/><span>{{ file.name }}</span><a-button type="text" danger aria-label="删除法人章" @click="removeLegalFile(file)"><DeleteOutlined /></a-button></div></div></div>
          </template>
          <a-upload-dragger v-else v-model:file-list="groupForm.legalFiles" :before-upload="()=>false" accept="image/*" list-type="picture"><div class="legal-upload-copy"><p class="ant-upload-text">点击或拖拽上传法人章图片</p><p class="ant-upload-hint">法人章保留在印章组层级</p></div></a-upload-dragger>
        </a-form-item>
      </a-form>
    </a-modal>
    <a-modal v-model:open="sealOpen" :title="sealForm.id?'编辑单章':'新增单章'" width="600px" @ok="saveSeal"><a-alert v-if="sealForm.source==='工商同步'" type="info" show-icon message="状态、启用时间和停用时间以工商为准；修改印章类型、名称或编码后，对应字段不再随工商同步更新" class="mb12"/><a-form layout="vertical"><a-row :gutter="16"><a-col :span="12"><a-form-item label="所属印章组"><a-input :value="currentGroup.groupNo" disabled/></a-form-item></a-col><a-col :span="12"><a-form-item label="数据来源"><a-input :value="sealForm.id?sealForm.source:'人工新建'" disabled/></a-form-item></a-col></a-row><a-row :gutter="16"><a-col :span="8"><a-form-item label="印章类型" name="type"><a-select v-model:value="sealForm.type" :options="typeOptions"/><div v-if="sealForm.source==='工商同步'" class="sync-hint">修改后，此字段不再随工商同步更新</div></a-form-item></a-col><a-col :span="8"><a-form-item label="状态" name="status"><a-select v-model:value="sealForm.status" :options="statusOptions" :disabled="sealForm.source==='工商同步'"/><div v-if="sealForm.source==='工商同步'" class="sync-hint">以工商为准</div></a-form-item></a-col><a-col :span="8"><a-form-item label="启用时间" name="enabledAt" :validate-status="enabledAtError?'error':''" :help="enabledAtError"><a-date-picker v-model:value="sealForm.date" show-time style="width:100%" :disabled="sealForm.source==='工商同步'"/><div v-if="sealForm.source==='工商同步'" class="sync-hint">以工商为准</div></a-form-item></a-col></a-row><a-form-item label="印章名称" name="name"><a-input v-model:value="sealForm.name" @blur="checkSameName"/><div v-if="sameName" class="warn">本组已有同名启用单章（{{sameName}}），请确认是否为换章后的新章</div><div v-if="sealForm.source==='工商同步'" class="sync-hint">修改后，此字段不再随工商同步更新</div></a-form-item><a-form-item label="印章编码" name="code"><a-input v-model:value="sealForm.code" placeholder="请输入印章编码"/><div v-if="sealForm.source==='工商同步'" class="sync-hint">修改后，此字段不再随工商同步更新</div></a-form-item><a-form-item label="备注" name="remark"><a-textarea v-model:value="sealForm.remark" :rows="3" :maxlength="200" show-count/></a-form-item><a-form-item v-if="!sealForm.id" label="标准图" required :validate-status="imageError?'error':''" :help="imageError?'请至少上传 1 张标准图':''"><a-upload-dragger v-model:file-list="sealForm.files" :before-upload="()=>false" multiple accept="image/*" list-type="picture"><div class="legal-upload-copy"><p class="ant-upload-text">点击或拖拽上传标准图</p><p class="ant-upload-hint">支持常见图片格式</p></div></a-upload-dragger></a-form-item></a-form></a-modal>
