  </div>
</template>

<script setup lang="ts">
import { computed, defineComponent, h, onMounted, reactive, ref, watch } from 'vue'
import dayjs from 'dayjs'
import { AnfeProTable } from '@anfe/vue-pro-components'
import { Button, message, Modal } from 'ant-design-vue'
import { CopyOutlined, DeleteOutlined, LeftOutlined, PlusOutlined } from '@ant-design/icons-vue'
type Library='company'|'address'|'power'; const runtimeAddedGroups:Record<Library,any[]>=(globalThis as any).__sealRuntimeGroups||{company:[],address:[],power:[]}; (globalThis as any).__sealRuntimeGroups=runtimeAddedGroups;const runtimeSealRecords:Record<string,any[]>=(globalThis as any).__sealRuntimeRecords||{};(globalThis as any).__sealRuntimeRecords=runtimeSealRecords;const runtimeLegendRecords:Record<string,any[]>=(globalThis as any).__sealRuntimeLegends||{};(globalThis as any).__sealRuntimeLegends=runtimeLegendRecords;const runtimeLogRecords:Record<string,any[]>=(globalThis as any).__sealRuntimeLogs||{};(globalThis as any).__sealRuntimeLogs=runtimeLogRecords;if(!Object.keys(runtimeSealRecords).length){try{Object.assign(runtimeSealRecords,JSON.parse(sessionStorage.getItem('seal-runtime-records')||'{}'));Object.assign(runtimeLegendRecords,JSON.parse(sessionStorage.getItem('seal-runtime-legends')||'{}'));Object.assign(runtimeLogRecords,JSON.parse(sessionStorage.getItem('seal-runtime-logs')||'{}'))}catch{}}let persistTimer:number|undefined;function persistSealRuntime(){window.clearTimeout(persistTimer);persistTimer=window.setTimeout(()=>{try{sessionStorage.setItem('seal-runtime-records',JSON.stringify(runtimeSealRecords));sessionStorage.setItem('seal-runtime-legends',JSON.stringify(runtimeLegendRecords));sessionStorage.setItem('seal-runtime-logs',JSON.stringify(runtimeLogRecords))}catch{}},300)} const props=withDefaults(defineProps<{libraryType:Library;initialView?:'list'|'group'|'seal';initialGroup?:any;initialSeal?:any}>(),{initialView:'list'})
const emit=defineEmits<{navigate:[target:string,payload?:any];back:[]}>()
